use spore_core::cell_service_action_gate_v1::{gate,Branch};
fn w(b:&[u8],i:usize)->u32{u32::from_le_bytes(b[i..i+4].try_into().unwrap())}
fn main(){let b=std::fs::read(std::env::args().nth(1).expect("native stdout")).unwrap();assert_eq!(b.len(),120);let cases=[(0,0),(1,1),(u32::MAX,u32::MAX),(1,2),(u32::MAX,1),(0x12345678,u32::MAX)];for(i,(current,requested))in cases.into_iter().enumerate(){let p=gate(1,current,requested,true).unwrap();let got=[if p.branch==Branch::Equal{1}else{2},p.current,p.requested];for(j,x)in got.into_iter().enumerate(){assert_eq!(x,w(&b,i*20+j*4),"case {i} word {j}")}let fp=w(&b,i*20+12);assert_eq!(fp&0xffff,0x27f);assert_eq!((fp>>16)&0x3840,0);assert_eq!(w(&b,i*20+16)&!0x3f,0x1f80);}println!("matched six retained service-token gates; both continuations pending");}
